package twobucket

import "errors"

// state is the amount of water currently in each bucket.
type state struct {
	one, two int
}

// goalReached reports whether s holds exactly goal liters in either bucket.
// It returns the name of the bucket that holds the goal and the amount
// left in the other bucket.
func (s state) goalReached(goal int) (bucket string, other int, ok bool) {
	switch {
	case s.one == goal:
		return "one", s.two, true
	case s.two == goal:
		return "two", s.one, true
	}
	return "", 0, false
}

// forbidden reports whether s violates the rule that, after any action,
// the starting bucket may not be empty while the other bucket is full.
func (s state) forbidden(startBucket string, capOne, capTwo int) bool {
	if startBucket == "one" {
		return s.one == 0 && s.two == capTwo
	}
	return s.two == 0 && s.one == capOne
}

// neighbors returns every state reachable from s in a single action:
// emptying a bucket, filling a bucket, or pouring one bucket into the other.
func (s state) neighbors(capOne, capTwo int) []state {
	out := make([]state, 0, 6)
	// Empty a bucket.
	out = append(out, state{0, s.two}, state{s.one, 0})
	// Fill a bucket.
	out = append(out, state{capOne, s.two}, state{s.one, capTwo})
	// Pour bucket one into bucket two.
	pour := min(s.one, capTwo-s.two)
	out = append(out, state{s.one - pour, s.two + pour})
	// Pour bucket two into bucket one.
	pour = min(s.two, capOne-s.one)
	out = append(out, state{s.one + pour, s.two - pour})
	return out
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// Solve determines the fewest actions required to measure exactly
// goalAmount liters, starting by filling startBucket ("one" or "two").
// It returns the name of the bucket that ends up holding the goal,
// the total number of actions (including the first fill), and the
// amount left in the other bucket.
func Solve(sizeBucketOne, sizeBucketTwo, goalAmount int, startBucket string) (string, int, int, error) {
	if sizeBucketOne == 0 {
		return "", 0, 0, errors.New("invalid first bucket size")
	}
	if sizeBucketTwo == 0 {
		return "", 0, 0, errors.New("invalid second bucket size")
	}
	if goalAmount == 0 {
		return "", 0, 0, errors.New("invalid goal amount")
	}
	if startBucket != "one" && startBucket != "two" {
		return "", 0, 0, errors.New("invalid start bucket name")
	}
	if goalAmount > sizeBucketOne && goalAmount > sizeBucketTwo {
		return "", 0, 0, errors.New("impossible")
	}
	// The amount in each bucket is always a multiple of the gcd of the
	// bucket sizes, so a goal that is not a multiple can never be reached.
	if goalAmount%gcd(sizeBucketOne, sizeBucketTwo) != 0 {
		return "", 0, 0, errors.New("impossible")
	}

	var start state
	if startBucket == "one" {
		start = state{sizeBucketOne, 0}
	} else {
		start = state{0, sizeBucketTwo}
	}

	// The first action is filling the starting bucket.
	if bucket, other, ok := start.goalReached(goalAmount); ok {
		return bucket, 1, other, nil
	}

	// Breadth-first search over states, level by level, so the first
	// state holding the goal uses the fewest actions.
	visited := map[state]bool{start: true}
	queue := []state{start}
	moves := 1
	for len(queue) > 0 {
		moves++
		var nextQueue []state
		for _, cur := range queue {
			for _, next := range cur.neighbors(sizeBucketOne, sizeBucketTwo) {
				if next.forbidden(startBucket, sizeBucketOne, sizeBucketTwo) || visited[next] {
					continue
				}
				if bucket, other, ok := next.goalReached(goalAmount); ok {
					return bucket, moves, other, nil
				}
				visited[next] = true
				nextQueue = append(nextQueue, next)
			}
		}
		queue = nextQueue
	}
	return "", 0, 0, errors.New("impossible")
}

